let heldListBusy = false;
let heldListError = "";
let heldListBranch = "";
let heldListLoaded = false;
let heldListPendingCount = 0;
let heldResumeBusy = false;
async function fetchCloudHeldSales(branchId) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), 15000);
  try {
    const headers = { "x-branch-id":branchId };
    if (appMode === "staff") headers["x-pos-workspace"] = "1";
    const response = await fetch("/api/held-sales?branchId=" + encodeURIComponent(branchId), { method:"GET", headers, cache:"no-store", signal:controller.signal });
    if (response.redirected || (response.headers.get("content-type") || "").includes("text/html")) throw Error("Sign in to this app in another tab, then return here and select Retry. Your current cart has not been changed.");
    let result;
    try { result = await response.json(); } catch { throw Error("The cloud returned an unreadable response. Select Retry; no held payment has been changed."); }
    if (response.status === 401 || response.status === 403) throw Error("Your branch session needs attention. Keep this cart open, sign in to your branch in another tab, then select Retry.");
    if (!response.ok) throw Error(result.error || "Cloud held payments could not be loaded. Select Retry.");
    if (!Array.isArray(result.heldSales) || result.heldSales.some(row => !row || !row.id || row.branch_id !== branchId || !row.payload || !Array.isArray(row.payload.items))) throw Error("The cloud held-payment list could not be verified. Select Retry.");
    return result.heldSales;
  } catch (error) {
    if (error.name === "AbortError") throw Error("Loading held payments timed out. Check the connection and select Retry.");
    if (error instanceof TypeError) throw Error("Could not reach cloud held payments. Check your connection and sign-in, then select Retry.");
    throw error;
  } finally { clearTimeout(timer); }
}
async function loadHeldSales() {
  if (heldListBusy || heldResumeBusy) return;
  const branchId = selectedPosBranchId;
  document.querySelector("#heldSalesPanel").classList.remove("hidden");
  heldListBusy = true; heldListError = ""; heldListLoaded = false; heldListPendingCount = 0;
  heldListBranch = branchId; heldSales = []; renderHeldSales();
  try {
    if (!branchId) throw Error("Open your branch with its PIN, then select Retry.");
    const remote = await fetchCloudHeldSales(branchId);
    let local = [], pending = [];
    if (appMode === "staff") {
      try {
        local = await offlineLoad("held-sales-local:" + branchId) || [];
        pending = await offlineQueue();
        if (!Array.isArray(local) || !Array.isArray(pending)) throw Error("Invalid device records");
      } catch { throw Error("Cloud holds were reached, but this device's pending payments could not be checked. No records were changed. Retry or ask for help before opening a hold."); }
    }
    if (branchId !== selectedPosBranchId) throw Error("The branch changed while loading. Select Retry for the current branch.");
    const pendingIds = new Set(pending.map(item => item.payload?.heldSaleId).filter(Boolean));
    const combined = [...local, ...remote.filter(item => !local.some(saved => saved.id === item.id))];
    heldListPendingCount = combined.filter(item => pendingIds.has(item.id)).length;
    heldSales = combined.filter(item => !pendingIds.has(item.id));
    heldListLoaded = true;
  } catch (error) { heldListError = error.message || "Held payments could not be loaded. Select Retry."; }
  finally { heldListBusy = false; renderHeldSales(); }
}
function renderHeldSales() {
  const panel = document.querySelector("#heldSalesPanel"), list = document.querySelector("#heldSalesList");
  const status = document.querySelector("#heldSalesStatus"), retry = document.querySelector("#retryHeldSales");
  const button = document.querySelector("#loadHeldSalesButton");
  button.disabled = heldListBusy || heldResumeBusy;
  button.textContent = heldListBusy ? "Loading held payments..." : "Held payments";
  retry.disabled = heldListBusy || heldResumeBusy;
  retry.hidden = !heldListError;
  if (heldListBusy) { status.textContent = "Loading held payments from the cloud..."; list.innerHTML = ""; return; }
  if (heldListError) { status.textContent = heldListError; list.innerHTML = ""; return; }
  if (!heldListLoaded) return;
  panel.classList.remove("hidden");
  const query = document.querySelector("#heldSalesSearch").value.trim().toLowerCase();
  const rows = heldSales.filter(hold => !query || [hold.customer_name, hold.customer_phone].some(value => String(value || "").toLowerCase().includes(query)));
  status.textContent = (heldSales.length ? "Cloud list loaded. Select a held payment to open it." : heldListPendingCount ? "No holds available to open." : "No held payments saved for this branch.") + (heldListPendingCount ? " " + heldListPendingCount + " held payment(s) have a checkout pending on this device and are hidden to prevent a duplicate payment." : "");
  list.innerHTML = rows.map(hold => '<div class="held-sale-row"><div><strong>' + esc(hold.customer_name) + '</strong><span>' + esc(hold.customer_phone) + ' · ' + esc(new Date(hold.updated_at).toLocaleString("en-AU")) + (hold.local ? ' · Saved on this device' : ' · Cloud saved') + '</span></div><b>' + money(hold.total_cents) + '</b><button class="secondary" type="button" data-resume-hold="' + esc(hold.id) + '"' + (heldResumeBusy ? ' disabled' : '') + '>Open payment</button></div>').join("");
  if (heldSales.length && !rows.length) list.innerHTML = '<p class="hint">No matching held payments. Clear the search to show all.</p>';
  list.querySelectorAll("[data-resume-hold]").forEach(button => button.addEventListener("click", () => resumeHeldSale(button.dataset.resumeHold)));
}
async function resumeHeldSale(id) {
  if (heldListBusy || heldResumeBusy) return;
  if (heldListBranch !== selectedPosBranchId) { heldListError = "The branch changed. Select Retry before opening a held payment."; renderHeldSales(); return; }
  heldResumeBusy = true; renderHeldSales();
  try { await resumeHeldSaleDraft(id); }
  catch (error) { setSaleMessage(error.message || "The held payment could not be opened.", true); }
  finally { heldResumeBusy = false; renderHeldSales(); }
}

